def fun(n,m,l1):
    if n>m:
        return 0
    l2 = dict((l,l1.count(l)) for l in set(l1))
    if len(set(l2.keys()))==1:
        return l2.get(l1[0])//n
    if len(set(l2.values()))==1:
        return l2.get(l1[0])
    a = 1
    b = max(l2.values()) + 1
    while b > a + 1:
        c = (a + b) // 2
        num = sum(x // c for x in l2.values())
        if num >= n:
            a = c
        else:
            b = c
    return a    
